+static bool hasNestedIfs(const CandidateIf &c) {
+  for (auto &g : c.thenGroups) {
+    if (!g.nestedIfs.empty()) {
+      return true;
+    }
+  }
+  for (auto &g : c.elseGroups) {
+    if (!g.nestedIfs.empty()) {
+      return true;
+    }
+  }
+  return false;
+}
